values.value:
[
  [
    {
      "fieldName": "ucinn_ascendv2__Designation__c",
      "required": true,
      "customFieldParams": {
        "type": "lookup",
        "customMetadata": "Gift_Processing_Designation_Lookup",
        "label": "Designation"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Acknowledgement_Description_Formula__c"
    },
    {
      "fieldName":"ucinn_ascendv2__G_L_Account__c",
      "hidden": true
    },
    {
      "fieldName": "ucinn_ascendv2__Amount__c",
      "toolTip": "This is the amount of the payment that is allocated for this designation.",
      "customFieldParams": {
        "type": "number",
        "formatter": "currency",
        "eventOnBlur": true,
        "eventOnChange": false,
        "step": ".01"
      }
    },
    {
      "fieldName": "custom__Stock_Percentage__c",
      "criteria": [
        {
          "isCreation": true,
          "tenderTypeCategory": "Stock Gift"
        },
        {
          "isEdit": true,
          "tenderTypeCategory": "Stock Gift"
        }
      ],
      "customFieldParams": {
        "type": "number",
        "label": "Stock Percentage",
        "formatter": "percent-fixed",
        "eventOnBlur": true,
        "eventOnChange": false,
        "step": "0.000001",
        "min": "0"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Non_Gift_Amount__c",
      "toolTip": "This is the amount of the payment that is allocated to non-gift items for this designation.",
      "customFieldParams": {
        "type": "number",
        "formatter": "currency",
        "eventOnBlur": true,
        "eventOnChange": false,
        "step": ".01"
      },
      "criteria": [
        {
          "tenderTypeCategory": "Cash",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')"
        },
        {
          "tenderTypeCategory": "Credit Card",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')"
        },
        {
          "tenderTypeCategory": "Wire",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')"
        },
        {
          "tenderTypeCategory": "Check",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')"
        },
        {
          "tenderTypeCategory": "Stock Gift",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')"
        }
      ]
    },
    {
      "fieldName": "ucinn_ascendv2__Face_Value__c",
      "customFieldParams": {
        "type": "number",
        "formatter": "currency",
        "eventOnBlur": true,
        "eventOnChange": false,
        "step": ".01"
      },
      "criteria": [
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGCGA (Charitable Gift Annuity)"
        },
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGCLT (Charitable Lead Trust)"
        },
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGCRT (Charitable Remainder Trust)"
        },
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGDAF (Distribution from outside Donor Advised Fund)"
        },
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGEST (Realized Estate Gift)"
        },
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGHBT (Charitable Remainder Trust Held by Others)"
        },
        {
          "transactionRecords.TransactionInformation.Opportunity.Type": "PGIRA (Distribution from IRA)"
        }
      ]
    },
    {
      "fieldName": "custom__Gift_Amount__c",
      "disabled": true,
      "toolTip": "This is a read-only field that is calculated based on the setting in; Custom Metadata Types | Gift Processing Settings | Payment Method to show the amount allocated to this designation that is a gift.",
      "criteria": [
        {
          "tenderTypeCategory": "Cash",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')",
          "paymentMethod": "Legacy"
        },
        {
          "tenderTypeCategory": "Credit Card",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')",
          "paymentMethod": "Legacy"
        },
        {
          "tenderTypeCategory": "Wire",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')",
          "paymentMethod": "Legacy"
        },
        {
          "tenderTypeCategory": "Check",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')",
          "paymentMethod": "Legacy"
        },
        {
          "tenderTypeCategory": "Stock Gift",
          "transactionRecords.TransactionInformation.Opportunity.Type": "$notEqual('Recurring')",
          "paymentMethod": "Legacy"
        }
      ],
      "customFieldParams": {
        "type": "number",
        "label": "Gift Amount",
        "formatter": "currency",
        "step": ".01"
      }
    },
    {
      "fieldName": "ucinn_ascendv2__Campaign__c",
      "customFieldParams": {
        "type": "lookup",
        "customMetadata": "Gift_Processing_Campaign_Lookup",
        "constituentId": "transactionRecords.DonorInformation.Id",
        "label": "Appeal"
      },
      "criteria": [
        {
          "transactionRecords.isContactDonor": true
        }
      ]
    },
    {
      "fieldName": "ucinn_ascendv2__Campaign__c",
      "customFieldParams": {
        "type": "lookup",
        "customMetadata": "Gift_Processing_Campaign_Lookup",
        "organizationId": "transactionRecords.DonorInformation.Id",
        "label": "Appeal"
      },
      "criteria": [
        {
          "transactionRecords.isContactDonor": false
        }
      ]
    },
    {
      "fieldName": "ucinn_ascendv2__Campaign__c",
      "customFieldParams": {
        "type": "lookup",
        "customMetadata": "Gift_Processing_Campaign_Lookup",
        "label": "Appeal"
      },
      "criteria": [
        {
          "transactionRecords.DonorInformation": "$Equal(null)"
        },
        {
          "transactionRecords.DonorInformation.Id": "$Equal(null)"
        }
      ]
    }
  ]
]
